303	static PyObject *copyMemory(PyObject *self, PyObject *args) {
304	  uint64_t dst_ptr;
305	  uint64_t src_ptr;
306	  size_t count;
307	  const char *direction_str;
308	  rtMemcpyKind_t copy_direction;
309	
310	  if (!PyArg_ParseTuple(args, "KKns", &dst_ptr, &src_ptr, &count,
311	                        &direction_str)) {
312	    return nullptr;
313	  }
314	
315	  if (strcmp(direction_str, "H2D") == 0) {
316	    copy_direction = RT_MEMCPY_HOST_TO_DEVICE;
317	  } else if (strcmp(direction_str, "D2H") == 0) {
318	    copy_direction = RT_MEMCPY_DEVICE_TO_HOST;
319	  } else {
320	    PyErr_SetString(PyExc_ValueError,
321	                    "Invalid copy direction. Must be 'H2D' or 'D2H'.");
322	    return nullptr;
323	  }
324	
325	  void *dst = (void *)dst_ptr;
326	  void *src = (void *)src_ptr;
327	
328	  rtError_t error = rtMemcpy(dst, count, src, count, copy_direction);
329	  if (error != RT_ERROR_NONE) {
330	    PyErr_Format(PyExc_RuntimeError, "rtMemcpy failed with error code: 0x%x",
331	                 error);
332	    return nullptr;
333	  }
334	
335	  Py_INCREF(Py_None);
336	  return Py_None;
